1	package indexroom
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"slices"
10		"strconv"
11		"unicode/utf8"
12	)
13	
14	// ErrInvalidSnapshot marks a rejected snapshot document: malformed or
15	// truncated JSON, trailing data after the object, an unknown version,
16	// missing, mistyped, unknown, or duplicated fields, a null where version,
17	// tip, height, hash, parent, or a transaction identifier is required,
18	// heights that do not ascend consecutively from 1, an empty or duplicated
19	// hash, a broken parent link, a version-2 timestamp that is missing or
20	// neither null nor a non-negative integer, a hash, parent, or transaction
21	// identifier whose JSON string carries invalid UTF-8 bytes or unpaired or
22	// misordered Unicode surrogate escapes, or a tip that disagrees with the
23	// block list. A rejected restore never changes the index.
24	var ErrInvalidSnapshot = errors.New("indexroom: invalid snapshot")
25	
26	const (
27		// snapshotVersion1 is the timestamp-less layout. It stays readable
28		// indefinitely; its blocks restore with missing timestamps.
29		snapshotVersion1 = 1
30		// snapshotVersion2 adds a required timestamp field to every block:
31		// either a non-negative Unix-seconds integer or null for missing time.
32		snapshotVersion2 = 2
33	)
34	
35	// snapshotDoc is the wire form of an exported main chain. Both layout
36	// versions share one shape: Version selects whether every block carries its
37	// Timestamp field.
38	type snapshotDoc struct {
39		Version int64           `json:"version"`
40		Tip     int64           `json:"tip"`
41		Blocks  []snapshotBlock `json:"blocks"`
42	}
43	
44	// snapshotBlock is the wire form of one block, shared by both versions.
45	// Height, hash, parent, and the transaction list follow the same rules in
46	// either layout. The timestamp is version 2 only and carried as a raw
47	// literal: nil is omitted altogether (version 1), "null" marks a missing
48	// time, and integer bytes render the Unix-seconds value (version 2). It
49	// stays the final field in every layout.
50	type snapshotBlock struct {
51		Height    int64           `json:"height"`
52		Hash      string          `json:"hash"`
53		Parent    string          `json:"parent"`
54		Txs       []string        `json:"txs"`
55		Timestamp json.RawMessage `json:"timestamp,omitempty"`
56	}
57	
58	// Export writes the current main chain to w as a JSON snapshot: a single
59	// object with version, tip, and the blocks ordered by ascending height, each
60	// carrying its transactions in order. The same main chain always produces
61	// the same bytes, regardless of the reorg, restore, or query history that
62	// led to it. Only blocks in effect at export time appear; nothing the index
63	// once held and later dropped is included.
64	//
65	// A chain whose blocks all lack timestamps keeps the original version-1
66	// layout, byte for byte. As soon as any block carries a timestamp the
67	// document is version 2 and every block includes a timestamp field: a
68	// non-negative integer or null for a missing timestamp.
69	//
70	// Export observes one complete chain state and never modifies the index.
71	// The chain is copied under the lock and serialized afterwards, so queries
72	// and appends proceed while the stream is still being written. A write
73	// failure is reported and leaves the index untouched.
74	func (index *Index) Export(w io.Writer) error {
75		doc := index.snapshotChain()
76		raw, err := json.Marshal(doc)
77		if err != nil {
78			panic(err) // snapshot docs only contain marshalable fields
79		}
80		n, err := w.Write(raw)
81		if err != nil {
82			return fmt.Errorf("indexroom: export snapshot: %w", err)
83		}
84		if n != len(raw) {
85			return fmt.Errorf("indexroom: export snapshot: %w", io.ErrShortWrite)
86		}
87		return nil
88	}
89	
90	// snapshotChain copies the current main chain into the export wire
91	// form: blocks by ascending height, each with its transactions copied in
92	// original order. This is the single place that turns stored blocks into the
93	// shared document fields, so both layout versions keep identical rules for
94	// height, hash, parent, and the transaction list; the only version-dependent
95	// field is the timestamp literal.
96	//
97	// The version is selected from the same chain copy. Any block carrying a
98	// timestamp — even a zero — makes the document version 2, after which every
99	// block gets a timestamp field, null where its time is missing; a chain
100	// whose blocks all lack times stays version 1 with no timestamp field.
101	func (index *Index) snapshotChain() snapshotDoc {
102		index.mu.Lock()
103		defer index.mu.Unlock()
104		version := int64(snapshotVersion1)
105		for height := int64(1); height <= index.Tip; height++ {
106			if index.Blocks[height].Time != nil {
107				version = snapshotVersion2
108				break
109			}
110		}
111		doc := snapshotDoc{
112			Version: version,
113			Tip:     index.Tip,
114			Blocks:  make([]snapshotBlock, 0, int(index.Tip)),
115		}
116		for height := int64(1); height <= index.Tip; height++ {
117			block := index.Blocks[height]
118			txs := make([]string, len(block.Txs))
119			copy(txs, block.Txs)
120			entry := snapshotBlock{
121				Height: block.Height,
122				Hash:   block.Hash,
123				Parent: block.Parent,
124				Txs:    txs,
125			}
126			if version == snapshotVersion2 {
127				entry.Timestamp = snapshotTimestampLiteral(block.Time)
128			}
129			doc.Blocks = append(doc.Blocks, entry)
130		}
131		return doc
132	}
133	
134	// snapshotMissingTimestamp is the raw JSON literal written for a block whose
135	// time is missing in a version-2 document.
136	var snapshotMissingTimestamp = json.RawMessage("null")
137	
138	// snapshotTimestampLiteral renders a stored block time as its version-2
139	// timestamp literal: null for a missing time, otherwise its non-negative
140	// Unix-seconds value as a bare integer. Stored times are guaranteed
141	// non-negative by Append, Reorg, and Restore validation.
142	func snapshotTimestampLiteral(time *int64) json.RawMessage {
143		if time == nil {
144			return snapshotMissingTimestamp
145		}
146		return json.RawMessage(strconv.AppendInt(nil, *time, 10))
147	}
148	
149	// restoreAppliedHookLocked is a test-only rendezvous invoked from Restore
150	// once the snapshot chain has fully replaced the old main chain, while
151	// index.mu is still held and before the call returns. It is nil in
152	// production; restore regression tests park a successful restore here with
153	// the new chain already in effect, so a QueryTimeStats issued at that
154	// instant is forced to wait and, once it runs, must observe the complete
155	// new chain.
156	var restoreAppliedHookLocked func(newTip int64)
157	
158	// Restore replaces the whole main chain with the snapshot read from r. The
159	// input must be exactly one snapshot object, optionally followed by
160	// whitespace; every block is validated — including heights ascending from 1,
161	// non-empty unique hashes, and parent linkage — before anything is applied.
162	// The first block's parent is exempt from linkage: it names the chain start
163	// and need not be indexed.
164	//
165	// The replacement takes effect as one complete operation: on success the
166	// index holds exactly the snapshot chain with no leftover heights or hashes,
167	// and on any failure — a read error or an invalid block discovered at the
168	// very end — the current chain and every previously issued cursor remain as
169	// they were. The stream is consumed and validated before the lock is taken,
170	// so the index stays queryable and appendable while the restore is reading.
171	//
172	// After a successful restore, cursors issued earlier by this same index keep
173	// working wherever the pinned range still matches and the tip still covers
174	// it; otherwise continuations fail with ErrQueryChanged as usual.
175	func (index *Index) Restore(r io.Reader) error {
176		tip, blocks, err := parseSnapshot(r)
177		if err != nil {
178			return err
179		}
180		stored := make(map[int64]Block, len(blocks))
181		byHash := make(map[string]int64, len(blocks))
182		for _, block := range blocks {
183			stored[block.Height] = block
184			byHash[block.Hash] = block.Height
185		}
186		index.mu.Lock()
187		index.Blocks = stored
188		index.ByHash = byHash
189		index.Tip = tip
190		if restoreAppliedHookLocked != nil {
191			restoreAppliedHookLocked(tip)
192		}
193		index.mu.Unlock()
194		return nil
195	}
196	
197	// snapshotReader mediates between the snapshot's io.Reader and the JSON
198	// decoder so a fault the reader reports mid-document cannot be mistaken for a
199	// truncated document.
200	//
201	// json.Decoder turns a clean io.EOF after a partial JSON value into
202	// io.ErrUnexpectedEOF, and its token/peek path also drops any error that
203	// arrives together with the final bytes of a chunk. Either behavior makes a
204	// reader-reported io.ErrUnexpectedEOF — bare or wrapped — indistinguishable
205	// from an honestly truncated stream, and can hide the fault altogether.
206	//
207	// snapshotReader therefore observes every underlying read: a normal io.EOF
208	// passes through untouched, while any other error is remembered in fault and,
209	// when it arrived together with bytes, withheld until the following read. The
210	// decoder consumes the delivered bytes first and then receives the fault as a
211	// separate error-only read, where it cannot be swallowed. The fault is sticky
212	// afterwards, so a reader that oddly resumes after failing can never let the
213	// snapshot be applied once a failure has already been reported.
214	type snapshotReader struct {
215		r       io.Reader
216		fault   error // first non-EOF error reported by r, if any
217		pending bool  // fault is due on the next read
218	}
219	
220	func (s *snapshotReader) Read(p []byte) (int, error) {
221		if s.pending {
222			s.pending = false
223			return 0, s.fault
224		}
225		if s.fault != nil {
226			return 0, s.fault
227		}
228		n, err := s.r.Read(p)
229		if err == nil || errors.Is(err, io.EOF) {
230			return n, err
231		}
232		if s.fault == nil {
233			s.fault = err
234		}
235		if n > 0 {
236			s.pending = true
237			return n, nil
238		}
239		return 0, err
240	}
241	
242	// parseSnapshot reads and fully validates one snapshot document. It returns
243	// the tip height and the validated blocks in ascending height order.
244	func parseSnapshot(r io.Reader) (int64, []Block, error) {
245		// A fault the underlying reader reports mid-document — including one
246		// delivered together with usable bytes — is observed via snapshotReader
247		// rather than inferred from the JSON decoder, which would conflate it with
248		// a clean io.EOF on truncated input.
249		reader := &snapshotReader{r: r}
250		dec := json.NewDecoder(reader)
251		// classify maps a decoder failure onto the snapshot error model, but a
252		// fault observed on the underlying reader always wins: the decoder turns a
253		// clean io.EOF after truncated input into io.ErrUnexpectedEOF, so the
254		// presence of a real reader fault is the only reliable way to tell a read
255		// failure from an honestly truncated document. Field context carried by
256		// err (for example which field was being read) is preserved, and the
257		// recorded fault stays in the chain even when the decoder reports a
258		// separate content error from bytes already buffered.
259		classify := func(err error) error {
260			if reader.fault == nil {
261				return classifySnapshotErr(err)
262			}
263			if !errors.Is(err, reader.fault) {
264				err = fmt.Errorf("%w: %v", reader.fault, err)
265			}
266			return fmt.Errorf("indexroom: read snapshot: %w", err)
267		}
268		tok, err := dec.Token()
269		if err != nil {
270			return 0, nil, classify(err)
271		}
272		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
273			return 0, nil, invalidSnapshot("snapshot must be a single JSON object")
274		}
275	
276		// Top-level fields are captured raw so blocks can be parsed with the
277		// strict schema matching the declared version, whatever the field order,
278		// and so null can be told apart from a zero value.
279		var (
280			rawVersion, rawTip   json.RawMessage
281			rawBlocks            json.RawMessage
282			haveVersion, haveTip bool
283			haveBlocks           bool
284			seen                 = map[string]bool{}
285		)
286		for dec.More() {
287			key, err := snapshotKey(dec)
288			if err != nil {
289				return 0, nil, classify(err)
290			}
291			if seen[key] {
292				return 0, nil, invalidSnapshot("duplicate field %q", key)
293			}
294			seen[key] = true
295			switch key {
296			case "version":
297				if err := dec.Decode(&rawVersion); err != nil {
298					return 0, nil, classify(fmt.Errorf("field %q: %w", key, err))
299				}
300				haveVersion = true
301			case "tip":
302				if err := dec.Decode(&rawTip); err != nil {
303					return 0, nil, classify(fmt.Errorf("field %q: %w", key, err))
304				}
305				haveTip = true
306			case "blocks":
307				if err := dec.Decode(&rawBlocks); err != nil {
308					return 0, nil, classify(fmt.Errorf("field %q: %w", key, err))
309				}
310				haveBlocks = true
311			default:
312				return 0, nil, invalidSnapshot("unknown field %q", key)
313			}
314		}
315		if _, err := dec.Token(); err != nil { // closing '}'
316			return 0, nil, classify(err)
317		}
318		// Only whitespace may follow the snapshot object. A reader fault that
319		// arrived together with the document's final bytes is held back by
320		// snapshotReader and surfaces here, ahead of any content validation below:
321		// once the stream failed, the document cannot be known to be complete, so
322		// the read failure takes precedence even when the buffered bytes already
323		// contain trailing data or a complete object.
324		if reader.fault != nil {
325			return 0, nil, fmt.Errorf("indexroom: read snapshot: %w", reader.fault)
326		}
327		if _, err := dec.Token(); err != io.EOF {
328			if err == nil {
329				return 0, nil, invalidSnapshot("trailing data after the snapshot object")
330			}
331			return 0, nil, classify(err)
332		}
333	
334		if !haveVersion {
335			return 0, nil, invalidSnapshot("missing field %q", "version")
336		}
337		if !haveTip {
338			return 0, nil, invalidSnapshot("missing field %q", "tip")
339		}
340		if !haveBlocks {
341			return 0, nil, invalidSnapshot("missing field %q", "blocks")
342		}
343		version, err := snapshotInt64(rawVersion, "version")
344		if err != nil {
345			return 0, nil, err
346		}
347		tip, err := snapshotInt64(rawTip, "tip")
348		if err != nil {
349			return 0, nil, err
350		}
351		if version != snapshotVersion1 && version != snapshotVersion2 {
352			return 0, nil, invalidSnapshot("unsupported version %d", version)
353		}
354	
355		blockDec := json.NewDecoder(bytes.NewReader(rawBlocks))
356		blocks, err := parseSnapshotBlocks(blockDec, version)
357		if err != nil {
358			return 0, nil, err
359		}
360		if _, err := blockDec.Token(); err != io.EOF {
361			if err == nil {
362				return 0, nil, invalidSnapshot("trailing data after the blocks array")
363			}
364			return 0, nil, classifySnapshotErr(err)
365		}
366	
367		lastHeight := int64(0)
368		if len(blocks) > 0 {
369			lastHeight = blocks[len(blocks)-1].Height
370		}
371		if tip != lastHeight {
372			return 0, nil, invalidSnapshot("tip %d does not match the last block height %d", tip, lastHeight)
373		}
374		return tip, blocks, nil
375	}
376	
377	// parseSnapshotBlocks reads the blocks array value, validating heights,
378	// hashes, parent links, and (for version 2) timestamps as it goes.
379	func parseSnapshotBlocks(dec *json.Decoder, version int64) ([]Block, error) {
380		tok, err := dec.Token()
381		if err != nil {
382			return nil, classifySnapshotErr(err)
383		}
384		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
385			return nil, invalidSnapshot("field %q must be an array", "blocks")
386		}
387		blocks := []Block{}
388		seenHash := map[string]bool{}
389		for dec.More() {
390			var block Block
391			if version == snapshotVersion2 {
392				block, err = parseSnapshotBlockV2(dec)
393			} else {
394				block, err = parseSnapshotBlock(dec)
395			}
396			if err != nil {
397				return nil, err
398			}
399			want := int64(len(blocks) + 1)
400			if block.Height != want {
401				return nil, invalidSnapshot("block height %d out of order, expected %d", block.Height, want)
402			}
403			if block.Hash == "" {
404				return nil, invalidSnapshot("block at height %d has an empty hash", block.Height)
405			}
406			if seenHash[block.Hash] {
407				return nil, invalidSnapshot("duplicate hash %q", block.Hash)
408			}
409			seenHash[block.Hash] = true
410			// The first block's parent names the chain start and is exempt from
411			// linkage; every later block must point at its predecessor.
412			if len(blocks) > 0 && block.Parent != blocks[len(blocks)-1].Hash {
413				return nil, invalidSnapshot("block at height %d does not link to its parent", block.Height)
414			}
415			blocks = append(blocks, block)
416		}
417		if _, err := dec.Token(); err != nil { // closing ']'
418			return nil, classifySnapshotErr(err)
419		}
420		return blocks, nil
421	}
422	
423	// parseSnapshotBlock reads one version-1 block object, requiring exactly the
424	// fields height, hash, parent, and txs.
425	func parseSnapshotBlock(dec *json.Decoder) (Block, error) {
426		var block Block
427		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs")
428		if err != nil {
429			return block, err
430		}
431		return finishSnapshotBlock(fields)
432	}
433	
434	// parseSnapshotBlockV2 reads one version-2 block object, requiring exactly
435	// the fields height, hash, parent, txs, and timestamp. Timestamp must be
436	// null or a non-negative integer; the block returns a nil time for null.
437	func parseSnapshotBlockV2(dec *json.Decoder) (Block, error) {
438		var block Block
439		fields, err := readSnapshotBlockObject(dec, "height", "hash", "parent", "txs", "timestamp")
440		if err != nil {
441			return block, err
442		}
443		if _, ok := fields["timestamp"]; !ok {
444			return block, invalidSnapshot("block is missing field %q", "timestamp")
445		}
446		block, err = finishSnapshotBlock(fields)
447		if err != nil {
448			return block, err
449		}
450		t, err := parseSnapshotTimestamp(fields["timestamp"])
451		if err != nil {
452			return Block{}, err
453		}
454		block.Time = t
455		return block, nil
456	}
457	
458	// readSnapshotBlockObject reads one block object and captures each known
459	// field's raw value. Fields are decoded only after the whole object is read,
460	// so a null can be rejected per field and a txs element error can name the
461	// block's height whatever order the fields arrive in.
462	func readSnapshotBlockObject(dec *json.Decoder, known ...string) (map[string]json.RawMessage, error) {
463		tok, err := dec.Token()
464		if err != nil {
465			return nil, classifySnapshotErr(err)
466		}
467		if delim, ok := tok.(json.Delim); !ok || delim != '{' {
468			return nil, invalidSnapshot("block must be a JSON object")
469		}
470		fields := map[string]json.RawMessage{}
471		for dec.More() {
472			key, err := snapshotKey(dec)
473			if err != nil {
474				return nil, classifySnapshotErr(err)
475			}
476			if _, dup := fields[key]; dup {
477				return nil, invalidSnapshot("duplicate block field %q", key)
478			}
479			if !slices.Contains(known, key) {
480				return nil, invalidSnapshot("unknown block field %q", key)
481			}
482			var raw json.RawMessage
483			if err := dec.Decode(&raw); err != nil {
484				return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", key, err))
485			}
486			fields[key] = raw
487		}
488		if _, err := dec.Token(); err != nil { // closing '}'
489			return nil, classifySnapshotErr(err)
490		}
491		return fields, nil
492	}
493	
494	// finishSnapshotBlock decodes the shared block fields from their raw values,
495	// requiring height, hash, parent, and txs and rejecting null for each.
496	func finishSnapshotBlock(fields map[string]json.RawMessage) (Block, error) {
497		var block Block
498		for _, field := range []string{"height", "hash", "parent", "txs"} {
499			if _, ok := fields[field]; !ok {
500				return block, invalidSnapshot("block is missing field %q", field)
501			}
502		}
503		var err error
504		if block.Height, err = snapshotInt64(fields["height"], "height"); err != nil {
505			return block, err
506		}
507		if block.Hash, err = snapshotString(fields["hash"], "hash", block.Height); err != nil {
508			return block, err
509		}
510		if block.Parent, err = snapshotString(fields["parent"], "parent", block.Height); err != nil {
511			return block, err
512		}
513		txs, err := parseSnapshotTxs(json.NewDecoder(bytes.NewReader(fields["txs"])), block.Height)
514		if err != nil {
515			return block, err
516		}
517		block.Txs = txs
518		return block, nil
519	}
520	
521	// snapshotInt64 decodes one required integer field, rejecting null rather
522	// than letting it pass as zero.
523	func snapshotInt64(raw json.RawMessage, field string) (int64, error) {
524		if isSnapshotNull(raw) {
525			return 0, invalidSnapshot("field %q must not be null", field)
526		}
527		var v int64
528		if err := json.Unmarshal(raw, &v); err != nil {
529			return 0, classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
530		}
531		return v, nil
532	}
533	
534	// snapshotString decodes one required string field, rejecting null rather
535	// than letting it pass as the empty string. The raw literal is also checked
536	// for invalid UTF-8 bytes and unpaired or misordered \uXXXX surrogate
537	// escapes, which the decoder would otherwise silently rewrite to U+FFFD;
538	// height identifies the block the field belongs to in the error.
539	func snapshotString(raw json.RawMessage, field string, height int64) (string, error) {
540		if isSnapshotNull(raw) {
541			return "", invalidSnapshot("field %q must not be null", field)
542		}
543		var s string
544		if err := json.Unmarshal(raw, &s); err != nil {
545			return "", classifySnapshotErr(fmt.Errorf("field %q: %w", field, err))
546		}
547		if !validSnapshotString(raw) {
548			return "", invalidSnapshot("block at height %d: field %q has invalid UTF-8 or unpaired surrogate escapes", height, field)
549		}
550		return s, nil
551	}
552	
553	// isSnapshotNull reports whether a raw field value is the JSON null literal.
554	func isSnapshotNull(raw json.RawMessage) bool {
555		return string(raw) == "null"
556	}
557	
558	// validSnapshotString reports whether raw is a JSON string literal whose
559	// content is valid UTF-8 and whose \uXXXX escapes contain no unpaired or
560	// misordered surrogates. The JSON decoder accepts both defects silently,
561	// rewriting the bad parts to U+FFFD, which could merge distinct identifiers;
562	// the raw bytes are checked here before the decoded value is trusted. A
563	// genuine U+FFFD — written literally or as a \ufffd escape — is valid
564	// UTF-8 and passes.
565	func validSnapshotString(raw json.RawMessage) bool {
566		if len(raw) < 2 || raw[0] != '"' || raw[len(raw)-1] != '"' {
567			return false
568		}
569		body := raw[1 : len(raw)-1]
570		for i := 0; i < len(body); {
571			b := body[i]
572			switch {
573			case b == '\\':
574				if i+1 >= len(body) {
575					return false
576				}
577				if body[i+1] != 'u' {
578					i += 2 // \", \\, \/, \b, \f, \n, \r, \t
579					continue
580				}
581				code, ok := snapshotHex4(body, i+2)
582				if !ok {
583					return false
584				}
585				i += 6
586				switch {
587				case code >= 0xD800 && code <= 0xDBFF:
588					// A high surrogate is only valid as the first half of a
589					// pair; the low half must follow immediately as an escape.
590					if i+6 > len(body) || body[i] != '\\' || body[i+1] != 'u' {
591						return false
592					}
593					low, ok := snapshotHex4(body, i+2)
594					if !ok || low < 0xDC00 || low > 0xDFFF {
595						return false
596					}
597					i += 6
598				case code >= 0xDC00 && code <= 0xDFFF:
599					return false // a low surrogate cannot appear on its own
600				}
601			case b < utf8.RuneSelf:
602				i++
603			default:
604				// DecodeRune returns RuneError with size 1 for invalid
605				// encoding; a genuine U+FFFD decodes with size 3.
606				r, size := utf8.DecodeRune(body[i:])
607				if r == utf8.RuneError && size <= 1 {
608					return false
609				}
610				i += size
611			}
612		}
613		return true
614	}
615	
616	// snapshotHex4 reads four hexadecimal digits starting at b[i].
617	func snapshotHex4(b []byte, i int) (rune, bool) {
618		if i+4 > len(b) {
619			return 0, false
620		}
621		var v rune
622		for _, c := range b[i : i+4] {
623			var d byte
624			switch {
625			case '0' <= c && c <= '9':
626				d = c - '0'
627			case 'a' <= c && c <= 'f':
628				d = c - 'a' + 10
629			case 'A' <= c && c <= 'F':
630				d = c - 'A' + 10
631			default:
632				return 0, false
633			}
634			v = v*16 + rune(d)
635		}
636		return v, true
637	}
638	
639	// parseSnapshotTimestamp reads one timestamp value: null for a missing
640	// timestamp, or a non-negative integer. Zero is stored as a real timestamp,
641	// distinct from null.
642	func parseSnapshotTimestamp(raw json.RawMessage) (*int64, error) {
643		var t *int64
644		if err := json.Unmarshal(raw, &t); err != nil {
645			return nil, classifySnapshotErr(fmt.Errorf("field %q: %w", "timestamp", err))
646		}
647		if t != nil && *t < 0 {
648			return nil, invalidSnapshot("timestamp must not be negative")
649		}
650		return t, nil
651	}
652	
653	// parseSnapshotTxs reads one txs array, preserving duplicates and empty
654	// identifiers exactly as written. A null element is rejected, naming the
655	// block's height and the element's zero-based position, and so is an
656	// element whose raw string carries invalid UTF-8 bytes or unpaired or
657	// misordered surrogate escapes.
658	func parseSnapshotTxs(dec *json.Decoder, height int64) ([]string, error) {
659		tok, err := dec.Token()
660		if err != nil {
661			return nil, classifySnapshotErr(err)
662		}
663		if delim, ok := tok.(json.Delim); !ok || delim != '[' {
664			return nil, invalidSnapshot("field %q must be an array of strings", "txs")
665		}
666		txs := []string{}
667		for dec.More() {
668			var raw json.RawMessage
669			if err := dec.Decode(&raw); err != nil {
670				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
671			}
672			if isSnapshotNull(raw) {
673				return nil, invalidSnapshot("block at height %d: txs element %d must not be null", height, len(txs))
674			}
675			var tx string
676			if err := json.Unmarshal(raw, &tx); err != nil {
677				return nil, classifySnapshotErr(fmt.Errorf("txs element: %w", err))
678			}
679			if !validSnapshotString(raw) {
680				return nil, invalidSnapshot("block at height %d: field %q element %d has invalid UTF-8 or unpaired surrogate escapes", height, "txs", len(txs))
681			}
682			txs = append(txs, tx)
683		}
684		if _, err := dec.Token(); err != nil { // closing ']'
685			return nil, classifySnapshotErr(err)
686		}
687		return txs, nil
688	}
689	
690	// snapshotKey reads the next object key and returns the decoder's error
691	// unwrapped so each caller can classify it against its own input source.
692	func snapshotKey(dec *json.Decoder) (string, error) {
693		tok, err := dec.Token()
694		if err != nil {
695			return "", err
696		}
697		key, ok := tok.(string)
698		if !ok {
699			return "", invalidSnapshot("object key must be a string")
700		}
701		return key, nil
702	}
703	
704	// invalidSnapshot builds an ErrInvalidSnapshot error with a specific reason.
705	func invalidSnapshot(format string, args ...any) error {
706		return fmt.Errorf("%w: %s", ErrInvalidSnapshot, fmt.Sprintf(format, args...))
707	}
708	
709	// classifySnapshotErr maps decoder failures onto the snapshot error model:
710	// malformed JSON, wrong value types, and truncation are snapshot errors,
711	// while anything else is an underlying read failure reported as-is.
712	func classifySnapshotErr(err error) error {
713		var syntaxErr *json.SyntaxError
714		var typeErr *json.UnmarshalTypeError
715		switch {
716		case errors.As(err, &syntaxErr), errors.As(err, &typeErr):
717			return fmt.Errorf("%w: %v", ErrInvalidSnapshot, err)
718		case errors.Is(err, io.EOF), errors.Is(err, io.ErrUnexpectedEOF):
719			return fmt.Errorf("%w: unexpected end of input", ErrInvalidSnapshot)
720		default:
721			return fmt.Errorf("indexroom: read snapshot: %w", err)
722		}
723	}
724

